class LauncherError(Exception):
  """An actionable launcher failure."""


def fText(pLanguage, pKey, **pFields):
  return dMessages.get(pLanguage, dMessages['en-US'])[pKey].format(**pFields)


def fRegular(pPath):
  if pPath.is_symlink() or (pPath.exists() and not pPath.is_file()):
    raise LauncherError(f'Unsafe file: {pPath}')


def fDirectory(pRoot, pRelative):
  vPath = pRoot
  for vPart in Path(pRelative).parts:
    vPath = vPath / vPart
    if vPath.is_symlink():
      raise LauncherError(f'Unsafe directory: {vPath}')
    vPath.mkdir(exist_ok=True)
  return vPath


def fHash(pData):
  return hashlib.sha256(pData).hexdigest()


class GithubRedirect(urllib.request.HTTPRedirectHandler):
  def mRedirect(pSelf, pRequest, pResponse, pCode, pMessage, pHeaders, pUrl):
    fGithubUrl(pUrl)
    return super().redirect_request(pRequest, pResponse, pCode, pMessage, pHeaders, pUrl)

  redirect_request = mRedirect


def fGithubUrl(pUrl):
  vParts = urllib.parse.urlsplit(pUrl)
  if (vParts.scheme != 'https' or vParts.hostname != 'raw.githubusercontent.com'
      or vParts.username or vParts.password or vParts.port not in (None, 443)):
    raise LauncherError('The runtime download must use HTTPS on raw.githubusercontent.com.')


def fDownload(pUrl, pDestination, pSha256):
  fGithubUrl(pUrl)
  fRegular(pDestination)
  if pDestination.exists() and pDestination.stat().st_size <= cMaxArchive:
    if fHash(pDestination.read_bytes()) == pSha256:
      return
  vOpener = urllib.request.build_opener(GithubRedirect())
  for vAttempt in range(3):
    vTemporary = None
    try:
      vRequest = urllib.request.Request(pUrl, headers={'User-Agent': 'mcOSisoCreator/1.1.0'})
      with vOpener.open(vRequest, timeout=30) as vResponse:
        if vResponse.status != 200:
          raise LauncherError(f'Unexpected HTTP status: {vResponse.status}')
        with tempfile.NamedTemporaryFile(dir=pDestination.parent, prefix='download-', delete=False) as vFile:
          vTemporary = Path(vFile.name)
          vDigest, vSize = hashlib.sha256(), 0
          while vData := vResponse.read(128 * 1024):
            vSize += len(vData)
            if vSize > cMaxArchive:
              raise LauncherError('The runtime archive exceeds the size limit.')
            vDigest.update(vData)
            vFile.write(vData)
          vFile.flush()
          os.fsync(vFile.fileno())
      if vDigest.hexdigest() != pSha256:
        raise LauncherError('Runtime SHA-256 mismatch; no downloaded code was executed.')
      os.replace(vTemporary, pDestination)
      return
    except (urllib.error.URLError, TimeoutError, ConnectionError) as vError:
      if isinstance(vError, urllib.error.HTTPError) and vError.code not in (404, 408, 429, 500, 502, 503, 504):
        raise LauncherError(f'Runtime download failed: HTTP {vError.code}') from vError
      if vAttempt == 2:
        raise LauncherError(f'Runtime download failed: {vError}') from vError
      time.sleep(vAttempt + 1)
    finally:
      if vTemporary is not None:
        vTemporary.unlink(missing_ok=True)


def fArchive(pData):
  if len(pData) > cMaxArchive:
    raise LauncherError('The runtime archive exceeds the size limit.')
  dFiles = {}
  with zipfile.ZipFile(io.BytesIO(pData)) as vZip:
    lMembers = vZip.infolist()
    if len(lMembers) > 150 or sum(vItem.file_size for vItem in lMembers) > cMaxExpanded:
      raise LauncherError('The expanded runtime exceeds the size limit.')
    for vItem in lMembers:
      vName = vItem.filename
      vPath = PurePosixPath(vName)
      vMode = vItem.external_attr >> 16
      if (not vName or vPath.is_absolute() or '..' in vPath.parts
          or '\\' in vName or ':' in vName or str(vPath) != vName
          or vName in dFiles or vItem.is_dir() or vItem.flag_bits & 1
          or (stat.S_IFMT(vMode) not in (0, stat.S_IFREG))):
        raise LauncherError(f'Unsafe archive member: {vName!r}')
      dFiles[vName] = vZip.read(vItem)
  if not cRequired.issubset(dFiles):
    raise LauncherError('The runtime archive is incomplete.')
  return dFiles


def fVerifyRuntime(pRuntime, pFiles):
  if pRuntime.is_symlink() or not pRuntime.is_dir():
    raise LauncherError(f'Unsafe runtime directory: {pRuntime}')
  sFound = set()
  for vPath in pRuntime.rglob('*'):
    if vPath.is_symlink():
      raise LauncherError(f'Unsafe runtime file: {vPath}')
    if vPath.is_dir():
      continue
    vName = vPath.relative_to(pRuntime).as_posix()
    if (vName not in pFiles or not vPath.is_file()
        or vPath.stat().st_size != len(pFiles[vName]) or vPath.read_bytes() != pFiles[vName]):
      raise LauncherError(f'The cached runtime was modified: {vPath}')
    sFound.add(vName)
  if sFound != set(pFiles):
    raise LauncherError(f'The cached runtime is incomplete: {pRuntime}')


def fInstall(pWork, pBundle, pSha256):
  vData = pBundle.read_bytes()
  if fHash(vData) != pSha256:
    raise LauncherError('Runtime SHA-256 mismatch; no downloaded code was executed.')
  dFiles = fArchive(vData)
  vRuntime = pWork / f'runtime-{pSha256}'
  if vRuntime.exists() or vRuntime.is_symlink():
    fVerifyRuntime(vRuntime, dFiles)
    return vRuntime
  with tempfile.TemporaryDirectory(dir=pWork, prefix='extract-') as vTemporary:
    vStage = Path(vTemporary) / 'runtime'
    vStage.mkdir()
    for vName, vContent in dFiles.items():
      vTarget = vStage / vName
      vTarget.parent.mkdir(parents=True, exist_ok=True)
      vTarget.write_bytes(vContent)
    fVerifyRuntime(vStage, dFiles)
    os.rename(vStage, vRuntime)
  return vRuntime


def fProjectFiles(pWorkspace, pRuntime):
  # Never overwrite existing project instructions or documentation.
  for vName in ('AGENTS.md', 'CLAUDE.md', 'ReglasParaEsteProyecto.md', '.gitignore'):
    vTarget = pWorkspace / vName
    if not vTarget.exists() and not vTarget.is_symlink():
      with vTarget.open('xb') as vFile:
        vFile.write((pRuntime / vName).read_bytes())


def fLaunch(pRuntime, pWorkspace, pArguments):
  dEnvironment = dict(os.environ, MCOS_ISO_CREATOR_WORKSPACE=str(pWorkspace))
  vCode = ('import sys; sys.path.insert(0, sys.argv.pop(1)); '
           'from macos_iso.cli import fMain; raise SystemExit(fMain())')
  with contextlib.ExitStack() as vStack:
    vInput = None if sys.stdin.isatty() else subprocess.DEVNULL
    if not sys.stdin.isatty() and '--non-interactive' not in pArguments:
      try:
        vInput = vStack.enter_context(open('/dev/tty', 'r', encoding='utf-8'))
      except OSError:
        pass
    vResult = subprocess.run([sys.executable, '-I', '-B', '-c', vCode,
      str(pRuntime / 'Scripts'), *pArguments], stdin=vInput, env=dEnvironment, check=False)
    return vResult.returncode if vResult.returncode >= 0 else 128 - vResult.returncode


def fMain(pArguments=None):
  vLanguage = 'en-US'
  try:
    vEarly = argparse.ArgumentParser(add_help=False, allow_abbrev=False)
    vEarly.add_argument('--language', choices=sorted(dMessages), default='en-US')
    vOptions, lUnused = vEarly.parse_known_args(pArguments)
    vLanguage = vOptions.language
    if sys.version_info < (3, 13) or not sys.platform.startswith('linux'):
      raise LauncherError(fText(vLanguage, 'platform'))
    vParser = argparse.ArgumentParser(add_help=False, allow_abbrev=False,
      description=fText(vLanguage, 'description'))
    vParser.add_argument('--directory', type=Path, default=Path.cwd() / 'mcOSisoCreator',
      dest='vDirectory', help=fText(vLanguage, 'directory'))
    vParser.add_argument('--launcher-help', action='store_true', dest='vHelp',
      help=fText(vLanguage, 'launcher_help'))
    vOptions, lArguments = vParser.parse_known_args(pArguments)
    if vOptions.vHelp:
      vParser.print_help()
      print(fText(vLanguage, 'forward'))
      return 0
    if len(cBundleSha256) != 64:
      raise LauncherError('This launcher has not been packaged.')
    vWorkspace = vOptions.vDirectory.resolve()
    vWorkspace.mkdir(parents=True, exist_ok=True)
    vWork = fDirectory(vWorkspace, '_/temp/bootstrap')
    import fcntl
    vLockPath = vWork / 'launcher.lock'
    fRegular(vLockPath)
    with vLockPath.open('a') as vLock:
      try:
        fcntl.flock(vLock, fcntl.LOCK_EX | fcntl.LOCK_NB)
      except BlockingIOError as vError:
        raise LauncherError(fText(vLanguage, 'locked')) from vError
      vBundle = vWork / f'runtime-{cBundleSha256}.zip'
      if '--quiet' not in lArguments and '--json' not in lArguments:
        print(fText(vLanguage, 'preparing', path=vWorkspace), file=sys.stderr, flush=True)
      fDownload(f'{cBaseUrl}/Releases/{vBundle.name}', vBundle, cBundleSha256)
      vRuntime = fInstall(vWork, vBundle, cBundleSha256)
      fProjectFiles(vWorkspace, vRuntime)
    return fLaunch(vRuntime, vWorkspace, lArguments)
  except KeyboardInterrupt:
    print(fText(vLanguage, 'cancelled'), file=sys.stderr)
    return 130
  except (LauncherError, OSError, ValueError, zipfile.BadZipFile) as vError:
    print(fText(vLanguage, 'error', detail=str(vError)), file=sys.stderr)
    return 1


if __name__ == '__main__':
  sys.dont_write_bytecode = True
  raise SystemExit(fMain())
